t.script:
//
        document.addEventListener('DOMContentLoaded', function() {
          var dInput  = document.getElementById('d-input');
          var eppInput= document.getElementById('epp-input');
          var pwdInput= document.getElementById('pwd');
          if (dInput)   dInput.addEventListener('input', function() { scheduleCheck(this.value); });
          if (eppInput) eppInput.addEventListener('input', function() {
            document.getElementById('epp_hidden').value = this.value;
          });
          if (pwdInput) pwdInput.addEventListener('input', function() { strength(this.value); });
        });

        var timer=null, lastDom='';
        function scheduleCheck(v){
          clearTimeout(timer);
          if(!v.trim()){reset();return;}
          timer=setTimeout(doCheck,900);
        }

        function doCheck(){
          var dom=document.getElementById('d-input').value.trim().toLowerCase();
          if(!dom){reset();return;}
          if(dom===lastDom)return;
          if(!/^[a-z0-9]([a-z0-9\-]{0,61}[a-z0-9])?(\.[a-z]{2,})+$/.test(dom)){
            show('unknown','&#9888;&#65039; Invalid domain format','Enter a valid domain like example.com',false);return;
          }
          lastDom=dom;
          show('checking','<span class="spin"></span>Checking availability...','',false);
          var btn=document.getElementById('chk-btn');
          btn.disabled=true;btn.textContent='...';
          fetch('/whm/check_domain',{
            method:'POST',
            headers:{'Content-Type':'application/json'},
            body:JSON.stringify({"jsonrpc":"2.0","method":"call","params":{"domain":dom}})
          }).then(function(r){return r.json();}).then(function(d){
            btn.disabled=false;btn.textContent='Check';
            var r=d.result||{};
            if(r.available===true){
              show('available','&#9989; '+dom+' is available!',
                'You can register this domain as part of your hosting setup.',true,'avail',dom);
            }else if(r.available===false){
              show('taken','&#10060; '+dom+' is already registered.',
                'You can transfer it to us, or use it with your own DNS.',true,'taken',dom);
            }else{
              show('unknown','&#9888;&#65039; '+(r.message||'Could not check'),
                'You can continue and set up your domain later.',false);
            }
          }).catch(function(){
            btn.disabled=false;btn.textContent='Check';
            show('unknown','&#9888;&#65039; Check failed','Please try again.',false);
          });
        }

        function show(cls,title,detail,actions,type,dom){
          var box=document.getElementById('d-result');
          box.className='d-result show '+cls;
          document.getElementById('d-title').innerHTML=title;
          document.getElementById('d-detail').textContent=detail;
          var act=document.getElementById('d-actions');
          act.innerHTML='';
          document.getElementById('epp-box').className='epp-box';
          document.getElementById('domain_action').value='none';
          if(!actions)return;
          if(type==='avail'){
            mkBtn(act,'da da-reg','&#128722; Register this domain',function(b){sel('register',b,act);});
            mkBtn(act,'da da-skp','Skip for now',function(b){sel('none',b,act);});
          }else if(type==='taken'){
            mkBtn(act,'da da-tra','&#8599;&#65039; Transfer to us',function(b){
              sel('transfer',b,act);
              document.getElementById('epp-box').className='epp-box show';
              document.getElementById('epp-input').focus();
            });
            mkBtn(act,'da da-ext','&#10003; I manage DNS elsewhere',function(b){sel('existing',b,act);});
            mkBtn(act,'da da-skp','Skip for now',function(b){sel('none',b,act);});
          }
        }

        function mkBtn(parent,cls,html,fn){
          var b=document.createElement('button');
          b.type='button';b.className=cls;b.innerHTML=html;
          b.onclick=function(){fn(b);};
          parent.appendChild(b);
        }

        function sel(action,btn,container){
          document.getElementById('domain_action').value=action;
          container.querySelectorAll('.da').forEach(function(b){b.classList.remove('sel');});
          btn.classList.add('sel');
          if(action!=='transfer'){
            document.getElementById('epp-box').className='epp-box';
            document.getElementById('epp_hidden').value='';
          }
        }

        function reset(){
          lastDom='';
          document.getElementById('d-result').className='d-result';
          document.getElementById('epp-box').className='epp-box';
          document.getElementById('domain_action').value='none';
        }

        function strength(v){
          var bar=document.getElementById('pwd-bar');
          var lbl=document.getElementById('pwd-lbl');
          var s=0;
          if(v.length>=10)s++;
          if(v.length>=14)s++;
          if(/[A-Z]/.test(v))s++;
          if(/[0-9]/.test(v))s++;
          if(/[^A-Za-z0-9]/.test(v))s++;
          var c=['#e74c3c','#e74c3c','#e74c3c','#f39c12','#27ae60','#1a7a3e'];
          var l=['Too short','Too weak for WHM','Too weak for WHM','Fair — add more complexity','Strong','Very strong'];
          bar.style.background=c[s]||'#dee2e6';
          bar.style.width=(s*20)+'%';
          if(s>=3){
            lbl.textContent=l[s];lbl.style.color=c[s];
          } else {
            lbl.innerHTML='WHM requires: min 10 chars + <strong>uppercase</strong> + <strong>number</strong> + <strong>symbol</strong>';
            lbl.style.color='#e74c3c';
          }
          return s;
        }

        // Block form submission if password too weak
        var form = document.querySelector('form');
        if(form){
          form.addEventListener('submit', function(e){
            var pwd = document.getElementById('pwd');
            var confirm = document.querySelector('input[name="confirm"]');
            var errEl = document.getElementById('pwd-error');
            var s = strength(pwd.value);
            if(s < 3){
              e.preventDefault();
              errEl.style.display='block';
              errEl.textContent='Password is too weak for WHM. Use at least 10 characters with uppercase, a number and a symbol (e.g. MyHost@2026!).';
              pwd.focus();
              return false;
            }
            if(pwd.value !== confirm.value){
              e.preventDefault();
              errEl.style.display='block';
              errEl.textContent='Passwords do not match.';
              confirm.focus();
              return false;
            }
            errEl.style.display='none';
          });
        }
      //
